import{_ as t,o as s,c as a,a3 as n}from"./chunks/framework.1Rq3Io9y.js";const g=JSON.parse('{"title":"Évaluation 2 — Rapport de faisabilité technique : proposition technique","description":"","frontmatter":{"title":"Évaluation 2 — Rapport de faisabilité technique : proposition technique","aside":false},"headers":[],"relativePath":"evaluations/evaluation-2.md","filePath":"evaluations/evaluation-2.md"}'),i={name:"evaluations/evaluation-2.md"};function r(l,e,o,u,c,d){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="evaluation-2-—-rapport-de-faisabilite-technique-proposition-technique" tabindex="-1">Évaluation 2 — Rapport de faisabilité technique : proposition technique <a class="header-anchor" href="#evaluation-2-—-rapport-de-faisabilite-technique-proposition-technique" aria-label="Permalink to &quot;Évaluation 2 — Rapport de faisabilité technique : proposition technique&quot;">​</a></h1><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>En bref</strong><br><ul class="list-disc pl-5"><li><strong>Pondération :</strong> 20 % de la note finale, dont 10 % de l&#39;évaluation pour la qualité du français.</li><li><strong>Équipe :</strong> votre équipe de la session, 2 ou 3 personnes.</li><li><strong>Remise :</strong> sur LÉA, au plus tard le <strong>mercredi 13 janvier, 18 h 30</strong> (début de la séance 13, au retour des fêtes).</li><li><strong>Format :</strong> la proposition technique seule, dans un fichier Word (<code>.docx</code>) fait à partir du gabarit et nommé <code>eval2-equipeN-nom1-nom2-nom3.docx</code>. <strong>Vous ne modifiez pas</strong> le rapport de l&#39;évaluation 1 : vous y renvoyez.</li><li><strong>Longueur :</strong> de 8 à 12 pages, sans compter la page de titre, la table des matières, les références et les annexes.</li><li><strong>Retard :</strong> 10 % par jour; aucun travail accepté après 7 jours.</li></ul><a href="./../fiches/eval2-gabarit-proposition.docx" download><strong>Télécharger le gabarit de la proposition (Word)</strong></a></div><hr><h2 id="la-mise-en-situation" tabindex="-1">La mise en situation <a class="header-anchor" href="#la-mise-en-situation" aria-label="Permalink to &quot;La mise en situation&quot;">​</a></h2><p>Votre évaluation technique a fait le portrait du projet d&#39;<a href="./../mandat/">Aventure Saint-Maurice</a> : ce qu&#39;il exige, ce qui le contraint, ce qui pourrait mal tourner et les technologies qui existent. Mélanie l&#39;a lue. Sa question, maintenant, est simple :</p><blockquote><p>« Qu&#39;est-ce que vous nous conseillez, combien ça coûte, et est-ce que ce sera prêt pour le 1<sup>er</sup> mars ? »</p></blockquote><p>La <strong>proposition technique</strong> y répond. C&#39;est la <strong>deuxième partie</strong> du rapport de faisabilité, remise dans son propre document. Le rapport de l&#39;évaluation 1 (le « rapport 1 ») reste tel que vous l&#39;avez remis : la proposition en résume l&#39;essentiel dans son introduction et y renvoie par numéro de section, par exemple « rapport 1, section 4.3 ».</p><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Cette fois, vous tranchez.</strong><br> Le rapport 1 décrivait sans recommander. La proposition <strong>choisit</strong> : un outil par question, des formats, des adaptations, un échéancier, un devis et une recommandation finale. Chaque choix s&#39;appuie sur ce que le rapport 1 a établi : une exigence, une contrainte, un risque, un essai ou une source. Un choix qui ne renvoie à rien de tout cela est une opinion. </div><hr><h2 id="competence-et-elements-vises" tabindex="-1">Compétence et éléments visés <a class="header-anchor" href="#competence-et-elements-vises" aria-label="Permalink to &quot;Compétence et éléments visés&quot;">​</a></h2><p><strong>HK29 — Évaluer la faisabilité technique d&#39;un projet</strong></p><ul><li>Élément 4 : proposer des moyens techniques.</li><li>Élément 5 : rédiger un rapport de faisabilité technique (seconde partie).</li></ul><hr><h2 id="le-lecteur" tabindex="-1">Le lecteur <a class="header-anchor" href="#le-lecteur" aria-label="Permalink to &quot;Le lecteur&quot;">​</a></h2><p>Toujours <strong>Mélanie Gauthier</strong>, avec Patrick Lavoie. Mêmes règles qu&#39;à l&#39;évaluation 1 : chaque terme technique est expliqué la première fois ou évité, les tableaux résument et le texte dit ce qu&#39;ils veulent dire pour l&#39;entreprise. Les commentaires reçus pour l&#39;évaluation 1 valent aussi pour ce rapport : appliquez-les dans votre façon d&#39;écrire.</p><p>Une nouveauté : Mélanie va <strong>prendre des décisions</strong> à partir de ce rapport. Ce qu&#39;elle doit décider et faire doit donc être écrit noir sur blanc, avec des dates.</p><hr><h2 id="le-contenu-du-rapport" tabindex="-1">Le contenu du rapport <a class="header-anchor" href="#le-contenu-du-rapport" aria-label="Permalink to &quot;Le contenu du rapport&quot;">​</a></h2><p>Le gabarit contient toutes ces sections, avec des consignes dans chacune. Il garde la page de titre et la table des matières de l&#39;évaluation 1.</p><h4 id="resume" tabindex="-1">Résumé <a class="header-anchor" href="#resume" aria-label="Permalink to &quot;Résumé&quot;">​</a></h4><p>Une demi-page au maximum, écrite en dernier : la <strong>recommandation</strong>, les outils retenus, le coût, la date de mise en ligne visée et les décisions que Mélanie doit prendre.</p><h4 id="_1-introduction" tabindex="-1">1. Introduction <a class="header-anchor" href="#_1-introduction" aria-label="Permalink to &quot;1. Introduction&quot;">​</a></h4><ul><li><strong>1.1 Le mandat et l&#39;évaluation technique, en bref</strong> : dix lignes au plus, pour qu&#39;on puisse lire la proposition sans le rapport 1. Le client, sa demande, la date et le budget, puis les contraintes déterminantes et les risques de la zone rouge, une ligne chacun, avec leur numéro (rapport 1, sections 4.3 et 5.3).</li><li><strong>1.2 Ce que couvre cette proposition</strong> : les choix, les formats, les adaptations, le temps, les coûts et la recommandation.</li><li><strong>1.3 Ce que la rencontre avec la cliente a changé</strong> : les questions posées à Mélanie à la séance 9 (tirées du rapport 1, section 7.2), sa réponse et ce qu&#39;elle change dans la proposition. Une question restée sans réponse devient une décision à la section 7.3.</li></ul><h4 id="_2-les-choix-techniques" tabindex="-1">2. Les choix techniques <a class="header-anchor" href="#_2-les-choix-techniques" aria-label="Permalink to &quot;2. Les choix techniques&quot;">​</a></h4><ul><li><strong>2.1 Les critères de choix</strong> : ce qui compte le plus pour ce client, tiré de vos exigences et de vos contraintes (rapport 1, sections 3 et 4), avec un poids pour chacun (par exemple : Mélanie peut modifier les prix seule, le coût annuel, la gestion des départs à 8 places).</li><li><strong>2.2 Les choix pour les cinq questions</strong> : pour chacune des questions Q1 à Q5, l&#39;outil ou la solution retenu, <strong>pourquoi</strong> (les critères, vos essais, vos sources), ce que vous écartez et pourquoi, et ce qui reste à vérifier. Partez des <a href="./../fiches/eval2-tableaux-communs.docx" download><strong>tableaux de comparaison communs</strong></a> (Word), remis avec la correction de l&#39;évaluation 1 : ce sont les mêmes pour toutes les équipes. Vous pouvez y ajouter un outil, à condition de dire pourquoi. Votre question peut s&#39;appuyer sur vos essais; pour les quatre autres, dites sur quoi repose le choix, et ce qu&#39;un essai devra confirmer avant de s&#39;engager. Pour Q4, on choisit <strong>où héberger et comment diffuser</strong> les vidéos; la préparation des fichiers va à la section 3.</li></ul><p>Un exemple sur un autre client, une boulangerie (ses critères et leurs poids), est dans les notes de la <a href="./../modules/01-faisabilite/08-estimer-et-chiffrer#choisir-avec-des-criteres">séance 8</a>.</p><h4 id="_3-les-formats-et-les-regles-de-mise-en-ligne" tabindex="-1">3. Les formats et les règles de mise en ligne <a class="header-anchor" href="#_3-les-formats-et-les-regles-de-mise-en-ligne" aria-label="Permalink to &quot;3. Les formats et les règles de mise en ligne&quot;">​</a></h4><ul><li><strong>3.1 Les règles par sorte de contenu</strong> : un tableau qui donne, pour chaque sorte de contenu, le format, la largeur, le poids maximal, l&#39;outil et la règle d&#39;accessibilité à respecter. (Vu à la séance 7 et au Lab 07.)</li><li><strong>3.2 Qui fait ce travail chez le client</strong> : qui, avec quel outil, et combien de temps ça lui prendra.</li></ul><h4 id="_4-les-adaptations-proposees" tabindex="-1">4. Les adaptations proposées <a class="header-anchor" href="#_4-les-adaptations-proposees" aria-label="Permalink to &quot;4. Les adaptations proposées&quot;">​</a></h4><ul><li><strong>4.1</strong> Pour chaque <strong>contrainte déterminante</strong> (rapport 1, section 4.3) et chaque <strong>risque de la zone rouge</strong> (rapport 1, section 5.3) : l&#39;adaptation que vous proposez et ce qu&#39;elle change pour le client. Exemple : le réseau est faible au quai, donc la liste des participants et de leurs allergies doit pouvoir s&#39;ouvrir sans connexion.</li><li><strong>4.2 Ce que vous ne proposez pas</strong> (l&#39;application mobile, le niveau de la rivière en direct, l&#39;ouverture l&#39;hiver…), et pourquoi, ou pour quand.</li></ul><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Une mesure, une adaptation : quelle différence ?</strong><br> Ne recopiez pas la section 5.3 du rapport 1. La <strong>mesure</strong> de l&#39;évaluation 1 disait ce qu&#39;il faut obtenir pour réduire le risque, sans choisir d&#39;outil : « la liste des participants doit rester consultable sans réseau ». L&#39;<strong>adaptation</strong> est la décision concrète de votre proposition qui obtient ce résultat : l&#39;outil retenu, la fonction à activer ou la façon de faire. Par exemple : « on active la liste hors ligne de l&#39;outil retenu à la section 2.2, et Patrick l&#39;ouvre au chalet avant chaque départ ». Renvoyez à la mesure par son numéro. </div><h4 id="_5-le-temps" tabindex="-1">5. Le temps <a class="header-anchor" href="#_5-le-temps" aria-label="Permalink to &quot;5. Le temps&quot;">​</a></h4><ul><li><strong>5.1 Les tâches et l&#39;estimation</strong> : le travail découpé en tâches, chacune estimée en trois chiffres (optimiste, probable, pessimiste), et l&#39;estimation retenue. (Vu à la séance 8.)</li><li><strong>5.2 L&#39;échéancier</strong> : un échéancier <strong>simple, par étapes</strong>, jusqu&#39;au 1<sup>er</sup> mars 2027 : ce qui est livré à chacune, ce que le client doit fournir et quand, et le <strong>coussin</strong> prévu pour les imprévus, dans un tableau suivi d&#39;un <strong>diagramme de Gantt</strong> (outils gratuits proposés à la <a href="./../modules/01-faisabilite/08-estimer-et-chiffrer#echeancier">séance 8</a>). Les cycles de travail agiles viendront aux séances 16 et 17; ils ne sont pas demandés ici.</li></ul><h4 id="_6-l-argent" tabindex="-1">6. L&#39;argent <a class="header-anchor" href="#_6-l-argent" aria-label="Permalink to &quot;6. L&#39;argent&quot;">​</a></h4><ul><li><strong>6.1 Les coûts uniques</strong> : la construction (les heures de l&#39;estimation × le taux de Studio Web FC) et ce qui s&#39;achète une seule fois.</li><li><strong>6.2 Les coûts annuels</strong> : les abonnements, le nom de domaine, les commissions, l&#39;entretien.</li><li><strong>6.3 Le total sur trois ans, comparé au budget</strong> : voir l&#39;encadré ci-dessous.</li><li><strong>6.4 Trois façons d&#39;entrer dans le budget</strong> : enlever des fonctionnalités, changer d&#39;outil, ou livrer le site en plusieurs étapes, avec ce que chacune fait économiser et ce que le client perd. (Vu à la séance 8.)</li></ul><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>À quoi comparer les coûts</strong><ul class="list-disc pl-5"><li>Le budget de Mélanie, <strong>8 000 $</strong> (ou <strong>13 000 $</strong> si la subvention de la MRC est accordée), sert à la <strong>construction</strong> (document 3 du mandat). Comparez-y les <strong>coûts uniques</strong> de la section 6.1.</li><li>Mélanie <strong>n&#39;a pas prévu de coûts annuels</strong>. Comparez les coûts annuels à ce que l&#39;entreprise paie aujourd&#39;hui pour son site (environ 300 $ par année pour Wix, selon elle), et dites-lui clairement combien elle devra prévoir chaque année.</li><li>Le <strong>total sur trois ans</strong> se donne à titre d&#39;information : c&#39;est ce que le projet coûtera vraiment.</li></ul></div><div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>Les hypothèses communes</strong><ul class="list-disc pl-5"><li>Studio Web FC facture <strong>75 $ de l&#39;heure</strong>.</li><li>Tous les montants sont <strong>avant taxes</strong>, le budget de Mélanie compris.</li><li>Les prix sont en <strong>dollars canadiens</strong>. Un prix en dollars américains est converti avec <strong>un seul taux pour tout le rapport</strong>, celui du jour où vous avez lu les prix, indiqué avec sa date et sa source (comme à l&#39;évaluation 1).</li><li>Le volume : environ 2 600 réservations et 9 000 participants par été (document 3 du mandat), sauf si vous justifiez une autre hypothèse.</li></ul></div><h4 id="_7-la-recommandation-finale" tabindex="-1">7. La recommandation finale <a class="header-anchor" href="#_7-la-recommandation-finale" aria-label="Permalink to &quot;7. La recommandation finale&quot;">​</a></h4><ul><li><strong>7.1 Notre recommandation.</strong> <strong>Le projet est-il faisable ?</strong> Oui, non, ou oui à certaines conditions : dites-le dans la première phrase. Puis le <strong>scénario recommandé</strong>, en une page au plus : ce qui sera en ligne le 1<sup>er</sup> mars, ce qui viendra ensuite, le coût sur trois ans.</li><li><strong>7.2 Les conditions</strong> : ce qui doit être vrai pour que ça marche.</li><li><strong>7.3 Ce que le client doit décider et faire</strong>, avec qui et avant quand : par exemple récupérer l&#39;accès au nom de domaine, choisir une politique d&#39;annulation, faire traduire la décharge par l&#39;avocat.</li></ul><h4 id="_8-references" tabindex="-1">8. Références <a class="header-anchor" href="#_8-references" aria-label="Permalink to &quot;8. Références&quot;">​</a></h4><p>Toutes les sources de la proposition, en style <a href="https://boite-outils.bib.umontreal.ca/citer/apa?p=5248896">APA 7</a>, y compris les tableaux de comparaison communs. Une source déjà citée dans le rapport 1 est citée de nouveau si la proposition s&#39;en sert.</p><h4 id="annexes" tabindex="-1">Annexes <a class="header-anchor" href="#annexes" aria-label="Permalink to &quot;Annexes&quot;">​</a></h4><ul><li><strong>A. Déclaration d&#39;utilisation de l&#39;IA générative</strong>, pour la proposition.</li><li><strong>B. Contribution des membres</strong>, pour la proposition, signée par tous.</li><li><strong>C. Le détail de l&#39;estimation</strong>, si votre liste de tâches dépasse 15 lignes dans la section 5.1.</li></ul><p>Les résultats de vos essais restent dans l&#39;annexe A du rapport 1 : citez-les (« rapport 1, annexe A ») sans les recopier.</p><hr><h2 id="l-intelligence-artificielle-generative" tabindex="-1">L&#39;intelligence artificielle générative <a class="header-anchor" href="#l-intelligence-artificielle-generative" aria-label="Permalink to &quot;L&#39;intelligence artificielle générative&quot;">​</a></h2><p>Les mêmes règles qu&#39;à l&#39;<a href="./evaluation-1#l-intelligence-artificielle-generative">évaluation 1</a>. En particulier, l&#39;IA générative ne doit pas <strong>produire les choix, l&#39;estimation ou le devis</strong> : ce sont les analyses que la grille évalue. Déclarez chaque usage dans l&#39;annexe A.</p><hr><h2 id="la-grille-d-evaluation" tabindex="-1">La grille d&#39;évaluation <a class="header-anchor" href="#la-grille-d-evaluation" aria-label="Permalink to &quot;La grille d&#39;évaluation&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">Critère</th><th style="text-align:left;">Ce qui est évalué</th><th style="text-align:right;">Points</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong>Organisation et clarté</strong></td><td style="text-align:left;">Résumé qui donne la recommandation, le coût et la date; renvois précis au rapport 1, sans recopie; tableaux lisibles; texte compréhensible pour une non-spécialiste</td><td style="text-align:right;">10</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><strong>Introduction et suivi de la rencontre</strong></td><td style="text-align:left;">Mandat, contraintes déterminantes et risques rouges résumés avec leur numéro; portée claire; réponses de la cliente à la séance 9 et ce qu&#39;elles changent</td><td style="text-align:right;">5</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong>Choix techniques</strong></td><td style="text-align:left;">Critères tirés des exigences et des contraintes; chaque choix justifié par les essais ou les sources; solutions écartées expliquées</td><td style="text-align:right;">20</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><strong>Formats et mise en ligne</strong></td><td style="text-align:left;">Format, largeur et poids pour chaque sorte de contenu; règles d&#39;accessibilité; qui fait le travail chez le client</td><td style="text-align:right;">10</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong>Adaptations</strong></td><td style="text-align:left;">Réponses concrètes aux contraintes déterminantes et aux risques de la zone rouge; ce qui n&#39;est pas proposé est expliqué</td><td style="text-align:right;">10</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><strong>Temps et échéancier</strong></td><td style="text-align:left;">Tâches complètes, estimation en trois chiffres, coussin, échéancier réaliste pour le 1<sup>er</sup> mars et ce que le client doit fournir</td><td style="text-align:right;">15</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong>Coûts sur trois ans</strong></td><td style="text-align:left;">Coûts uniques et annuels, hypothèses indiquées, comparaison au budget, trois options pour y entrer</td><td style="text-align:right;">15</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><strong>Recommandation finale</strong></td><td style="text-align:left;">Claire dès la première phrase, cohérente avec tout le rapport; conditions et décisions du client avec des dates</td><td style="text-align:right;">5</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;"><strong>Qualité du français</strong></td><td style="text-align:left;">Évaluée sur un extrait d&#39;environ 150 mots choisi par l&#39;enseignant, selon la Politique du français de la DFCSE</td><td style="text-align:right;">10</td></tr><tr><td style="text-align:center;"></td><td style="text-align:left;"></td><td style="text-align:left;"><strong>Total</strong></td><td style="text-align:right;"><strong>100</strong></td></tr></tbody></table><div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>Ce qui fait perdre des points rapidement</strong><ul class="list-disc pl-5"><li>Un choix qui ne renvoie à aucune exigence, contrainte, essai ou source.</li><li>Un outil retenu malgré une limite notée dans le rapport 1, sans dire comment on la contourne.</li><li>Un devis sans les coûts annuels, ou avec des dollars américains non convertis.</li><li>Un échéancier qui se termine le 28 février, sans coussin, ou qui oublie ce que le client doit fournir.</li><li>Une fonctionnalité promise qui ne figure ni dans l&#39;estimation ni dans le devis.</li><li>Une recommandation finale qui ne dit pas clairement oui ou non.</li><li>Les annexes A ou B manquantes, ou l&#39;annexe C absente quand la liste des tâches dépasse 15 lignes.</li></ul></div><hr><h2 id="le-calendrier-conseille" tabindex="-1">Le calendrier conseillé <a class="header-anchor" href="#le-calendrier-conseille" aria-label="Permalink to &quot;Le calendrier conseillé&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Séance</th><th style="text-align:left;">Date</th><th style="text-align:left;">Ce que vous y faites pour la proposition</th></tr></thead><tbody><tr><td style="text-align:center;">7</td><td style="text-align:left;">11 nov.</td><td style="text-align:left;">Le Lab 07 porte sur les formats et les règles de mise en ligne : ce que vous y produisez devient votre <strong>section 3</strong>. Commencez aussi la <strong>section 2.1</strong> (les critères de choix), à partir de vos exigences et de vos contraintes</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;">18 nov.</td><td style="text-align:left;">Le rapport de l&#39;évaluation 1 vous est rendu corrigé, avec des <strong>tableaux de comparaison communs</strong> pour les cinq questions. La séance porte sur les critères de choix, l&#39;estimation du temps et le devis : avancez les <strong>sections 2</strong> (choix techniques), <strong>5</strong> (temps) et <strong>6</strong> (argent)</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;">25 nov.</td><td style="text-align:left;">Rencontre avec le client : apportez <strong>cinq questions</strong>, choisies à la fin du Lab 08 parmi celles du rapport 1 (section 7.2). Notez ses réponses dans la <strong>section 1.3</strong>, puis ajustez les <strong>sections 2 et 4</strong>. N&#39;attendez pas la rencontre pour écrire la section 2</td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;">2 déc.</td><td style="text-align:left;">15 minutes de questions sur l&#39;évaluation 2 au début de la séance. À la maison : écrire les sections <strong>1.1</strong>, <strong>1.2</strong> et <strong>7</strong>, puis le résumé</td></tr><tr><td style="text-align:center;">—</td><td style="text-align:left;">21 déc. au 10 janv.</td><td style="text-align:left;">Vacances des fêtes. Gardez du temps pour la relecture par une autre personne de l&#39;équipe</td></tr><tr><td style="text-align:center;">13</td><td style="text-align:left;">13 janv.</td><td style="text-align:left;"><strong>Remise</strong> avant 18 h 30</td></tr></tbody></table><hr><h2 id="la-liste-de-verification-avant-la-remise" tabindex="-1">La liste de vérification avant la remise <a class="header-anchor" href="#la-liste-de-verification-avant-la-remise" aria-label="Permalink to &quot;La liste de vérification avant la remise&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Le rapport est fait à partir du gabarit : page de titre à jour, table des matières mise à jour, consignes en gris supprimées</span></label></li><li><label><input type="checkbox"><span class="check-text">Le résumé donne la recommandation, le coût et la date de mise en ligne</span></label></li><li><label><input type="checkbox"><span class="check-text">L&#39;introduction se lit sans le rapport 1, et chaque renvoi au rapport 1 donne le numéro de la section</span></label></li><li><label><input type="checkbox"><span class="check-text">La section 1.3 donne les réponses de Mélanie et ce qu&#39;elles changent</span></label></li><li><label><input type="checkbox"><span class="check-text">Chaque choix de la section 2 renvoie à une exigence, une contrainte, un essai ou une source</span></label></li><li><label><input type="checkbox"><span class="check-text">Chaque contrainte déterminante et chaque risque rouge ont leur adaptation (section 4), qui renvoie à la mesure du rapport 1 sans la recopier</span></label></li><li><label><input type="checkbox"><span class="check-text">Chaque fonctionnalité promise a ses heures dans l&#39;estimation et son coût dans le devis</span></label></li><li><label><input type="checkbox"><span class="check-text">L&#39;échéancier finit avant le 1<sup>er</sup> mars, avec un coussin, et dit ce que le client doit fournir et quand</span></label></li><li><label><input type="checkbox"><span class="check-text">Les coûts sont en dollars canadiens et avant taxes, avec un seul taux de change; les coûts uniques sont comparés à 8 000 $ et à 13 000 $, les coûts annuels à ce que le client paie aujourd&#39;hui</span></label></li><li><label><input type="checkbox"><span class="check-text">La première phrase de la section 7 dit si le projet est faisable</span></label></li><li><label><input type="checkbox"><span class="check-text">Le texte a été relu par une autre personne de l&#39;équipe que celle qui l&#39;a écrit, et passé dans un correcteur</span></label></li><li><label><input type="checkbox"><span class="check-text">Les annexes A et B sont présentes (et l&#39;annexe C au besoin)</span></label></li><li><label><input type="checkbox"><span class="check-text">Le fichier est nommé correctement et déposé sur LÉA avant 18 h 30 le 13 janvier</span></label></li></ul>',57)])])}const h=t(i,[["render",r]]);export{g as __pageData,h as default};
